/* Авторская практика ЕГЭ по электромагнитной индукции. */
(() => {
  const variants = [
    ['Магнитный поток через контур', 'мВб', n => [
      `Плоский контур площадью ${20*n} см² находится в однородном поле 0,5 Тл. Вектор индукции перпендикулярен плоскости контура. Найди магнитный поток в мВб.`, n,
      'Поле направлено вдоль нормали, поэтому Φ = BS.',
      `S = ${2*n}·10⁻³ м². Подстановка даёт Φ = ${n}·10⁻³ Вб = ${n} мВб.`
    ]],
    ['Поворот рамки', 'мВб', n => [
      `Рамку площадью ${50*n} см² поворачивают в однородном поле 0,4 Тл. Угол между нормалью к рамке и полем увеличивается с 0° до 60°. Найди модуль изменения потока в мВб.`, n,
      'Поток через рамку Φ = BS cos α, где α — угол между полем и нормалью.',
      `|ΔΦ| = 0,4 · ${50*n}·10⁻⁴ · (1 − 0,5) Вб = ${n} мВб.`
    ]],
    ['ЭДС в многовитковой катушке', 'В', n => [
      `В катушке ${10*n} одинаковых витков. Поток через каждый виток равномерно уменьшается от 18 до 6 мВб за 0,12 с. Найди модуль ЭДС индукции в вольтах.`, n,
      'Изменение потока через один виток по модулю равно 12 мВб.',
      `|ε| = N|ΔΦ|/Δt = ${10*n} · 0,012/0,12 = ${n} В.`
    ]],
    ['Скорость изменения поля', 'Тл/с', n => [
      `Катушка из 100 витков площадью 20 см² каждый расположена перпендикулярно однородному магнитному полю. При равномерном изменении поля возникла ЭДС с модулем ${n} В. Найди модуль скорости изменения индукции в Тл/с.`, 5*n,
      'Когда нормаль к виткам параллельна полю, |ε| = NS|ΔB|/Δt.',
      `NS = 100 · 0,002 = 0,2 м². Скорость изменения индукции равна ${n}/0,2 = ${5*n} Тл/с.`
    ]],
    ['ЭДС движущегося стержня', 'В', n => [
      `Стержень длиной 0,4 м скользит по параллельным рельсам со скоростью ${5*n} м/с. Стержень перпендикулярен рельсам, поле 0,5 Тл перпендикулярно их плоскости. Найди модуль ЭДС в стержне в вольтах.`, n,
      'За время Δt площадь контура изменяется на lvΔt, поэтому модуль ЭДС равен Blv.',
      `|ε| = 0,5 · 0,4 · ${5*n} = ${n} В.`
    ]],
    ['Заряд в индукционном контуре', 'мКл', n => [
      `Замкнутый одновитковый контур сопротивлением 4 Ом находится в меняющемся поле. Поток через него монотонно увеличился на ${4*n} мВб. Самоиндукцией пренебреги. Найди модуль заряда, прошедшего через сечение проводника, в мКл.`, n,
      'Из I = ε/R и закона Фарадея следует |q| = |ΔΦ|/R при монотонном изменении потока.',
      `Поскольку 1 мВб/Ом = 1 мКл, получаем |q| = ${4*n}/4 = ${n} мКл.`
    ]],
    ['ЭДС самоиндукции', 'мВ', n => [
      `Индуктивность катушки 40 мГн. За 0,2 с ток в катушке равномерно уменьшается на ${n} А. Найди модуль ЭДС самоиндукции в милливольтах.`, 200*n,
      'Модуль ЭДС самоиндукции равен L|ΔI|/Δt.',
      `|ε| = 0,04 · ${n}/0,2 В = ${200*n} мВ.`
    ]],
    ['Энергия магнитного поля катушки', 'мДж', n => [
      `Ток в катушке индуктивностью 80 мГн вырос с ${n} до ${2*n} А. Найди прирост энергии магнитного поля в мДж.`, 120*n*n,
      'Энергия поля катушки W = LI²/2. Вычисли разность энергий.',
      `ΔW = 0,08 · (${2*n}² − ${n}²)/2 Дж = ${120*n*n} мДж.`
    ]],
    ['Мощность в цепи со стержнем', 'Вт', n => [
      `Проводящий стержень длиной 0,5 м скользит по рельсам со скоростью ${4*n} м/с перпендикулярно стержню. Поле 1 Тл направлено перпендикулярно плоскости рельсов. Сопротивление цепи 4 Ом, самоиндукцией пренебреги. Найди тепловую мощность в ваттах.`, n*n,
      `ЭДС движения |ε| = Blv = 1 · 0,5 · ${4*n} = ${2*n} В.`,
      `По закону Ома и закону Джоуля — Ленца P = ε²/R = ${2*n}²/4 = ${n*n} Вт.`
    ]],
    ['Торможение проводящей перемычки', 'Н', n => [
      `Стержень длиной 0,5 м скользит без трения по горизонтальным рельсам со скоростью ${8*n} м/с перпендикулярно стержню. Однородное поле 1 Тл перпендикулярно плоскости рельсов, сопротивление замкнутой цепи 2 Ом. Какую силу в ньютонах нужно приложить вдоль рельсов, чтобы поддерживать скорость? Самоиндукцией пренебреги.`, n,
      `ЭДС движения равна Blv = ${4*n} В, ток I = |ε|/R = ${2*n} А.`,
      `По правилу Ленца сила Ампера тормозит стержень. Для равномерного движения тяга должна уравновешивать её: F = BIl = 1 · ${2*n} · 0,5 = ${n} Н.`
    ]]
  ];

  for (const [index, [title, unit, build]] of variants.entries()) {
    for (let variant = 1; variant <= 15; variant++) {
      const [question, answer, ...steps] = build(variant + 1);
      const category = index === 6 || index === 7 ? 249 : 364;
      tasks.push({
        id: `ege-physics-induction-${index + 1}-${variant}`,
        grade: 11,
        domain: 'physics',
        subject: 'physics',
        exam: 'ege',
        topic: 0,
        topicName: 'Электромагнитная индукция',
        examTopic: 'physics-ege-induction',
        level: index < 3 ? 0 : index < 7 ? 1 : 2,
        title, question, unit, answer, steps,
        hints: [steps[0]],
        solution: steps.join(' '),
        review: {plan: steps[0]},
        source: {
          name: 'Решу ЕГЭ',
          id: category,
          type: 'тематический каталог',
          url: `https://phys-ege.sdamgia.ru/test?category_id=${category}&filter=all`,
          note: 'Авторская задача МатКлуба. По ссылке доступна дополнительная практика по теме.'
        }
      });
    }
  }
})();

